import boto3

cognito_idp = boto3.client('cognito-idp')

def fetch_and_normalize_profile_claims(access_token):
    try:
        response = cognito_idp.get_user(
            AccessToken=access_token
        )
        user_attributes = {attr['Name']: attr['Value'] for attr in response['UserAttributes']}
        normalized_claims = {
            'username': user_attributes.get('username', ''),
            'email': user_attributes.get('email', ''),
            'phone_number': user_attributes.get('phone_number', ''),
            'name': user_attributes.get('name', ''),
            'given_name': user_attributes.get('given_name', ''),
            'family_name': user_attributes.get('family_name', ''),
        }
        return normalized_claims
    except Exception as e:
        print(f'Error fetching profile claims: {e}')
        return None

import os
from flask import Flask, request
from google.oauth2 import id_token
from google.auth.transport import requests

app = Flask(__name__)

@app.route('/oauth_callback', methods=['GET'])
def oauth_callback():
    auth_code = request.args.get('code')
    try:
        id_info = id_token.verify_oauth2_token(auth_code, requests.Request(), os.getenv('GOOGLE_CLIENT_ID'))
        if id_info['aud']!= os.getenv('GOOGLE_CLIENT_ID'):
            raise ValueError('Invalid audience.')
        user_id = id_info['sub']
        access_token = id_info['access_token']
        return {'user_id': user_id, 'access_token': access_token}
    except ValueError:
        return 'Invalid token', 400

if __name__ == '__main__':
    app.run(port=5000)
